 61	func loadDir(ctx context.Context, dirPath string) ([]string, *dirStats, error) {
 62		var children []string
 63		stats := &dirStats{}
 64	
 65		dirInfo, err := os.Stat(dirPath)
 66		if err != nil {
 67			log.Error(ctx, "Error stating dir", "path", dirPath, err)
 68			return nil, nil, err
 69		}
 70		stats.ModTime = dirInfo.ModTime()
 71	
 72		dir, err := os.Open(dirPath)
 73		if err != nil {
 74			log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
 75			return children, stats, err
 76		}
 77		defer dir.Close()
 78	
 79		dirEntries := fullReadDir(ctx, dir)
 80		for _, entry := range dirEntries {
 81			isDir, err := isDirOrSymlinkToDir(dirPath, entry)
 82			// Skip invalid symlinks
 83			if err != nil {
 84				log.Error(ctx, "Invalid symlink", "dir", filepath.Join(dirPath, entry.Name()), err)
 85				continue
 86			}
 87			if isDir && !isDirIgnored(dirPath, entry) && isDirReadable(dirPath, entry) {
 88				children = append(children, filepath.Join(dirPath, entry.Name()))
 89			} else {
 90				fileInfo, err := entry.Info()
 91				if err != nil {
 92					log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
 93					return children, stats, err
 94				}
 95				if fileInfo.ModTime().After(stats.ModTime) {
 96					stats.ModTime = fileInfo.ModTime()
 97				}
 98				switch {
 99				case model.IsAudioFile(entry.Name()):
100					stats.AudioFilesCount++
101				case model.IsValidPlaylist(entry.Name()):
102					stats.HasPlaylist = true
103				case model.IsImageFile(entry.Name()):
104					stats.Images = append(stats.Images, entry.Name())
105					if fileInfo.ModTime().After(stats.ImagesUpdatedAt) {
106						stats.ImagesUpdatedAt = fileInfo.ModTime()
107					}
108				}
109			}
110		}
111		return children, stats, nil
112	}
