114	// fullReadDir reads all files in the folder, skipping the ones with errors.
115	// It also detects when it is "stuck" with an error in the same directory over and over.
116	// In this case, it and returns whatever it was able to read until it got stuck.
117	// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
118	func fullReadDir(ctx context.Context, dir fs.ReadDirFile) []os.DirEntry {
119		var allDirs []os.DirEntry
120		var prevErrStr = ""
121		for {
122			dirs, err := dir.ReadDir(-1)
123			allDirs = append(allDirs, dirs...)
124			if err == nil {
125				break
126			}
127			log.Warn(ctx, "Skipping DirEntry", err)
128			if prevErrStr == err.Error() {
129				log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
130				break
131			}
132			prevErrStr = err.Error()
133		}
134		sort.Slice(allDirs, func(i, j int) bool { return allDirs[i].Name() < allDirs[j].Name() })
135		return allDirs
136	}
