138	// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
139	// system directory, or a symbolic link to a directory. Note that if the dirEnt
140	// is not a directory but is a symbolic link, this method will resolve by
141	// sending a request to the operating system to follow the symbolic link.
142	// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
143	// efficiency for go 1.16 and beyond
144	func isDirOrSymlinkToDir(baseDir string, dirEnt fs.DirEntry) (bool, error) {
145		if dirEnt.IsDir() {
146			return true, nil
147		}
148		if dirEnt.Type()&os.ModeSymlink == 0 {
149			return false, nil
150		}
151		// Does this symlink point to a directory?
152		fileInfo, err := os.Stat(filepath.Join(baseDir, dirEnt.Name()))
153		if err != nil {
154			return false, err
155		}
156		return fileInfo.IsDir(), nil
157	}
