159	// isDirIgnored returns true if the directory represented by dirEnt contains an
160	// `ignore` file (named after consts.SkipScanFile)
161	func isDirIgnored(baseDir string, dirEnt fs.DirEntry) bool {
162		// allows Album folders for albums which e.g. start with ellipses
163		name := dirEnt.Name()
164		if strings.HasPrefix(name, ".") && !strings.HasPrefix(name, "..") {
165			return true
166		}
167		if runtime.GOOS == "windows" && strings.EqualFold(name, "$RECYCLE.BIN") {
168			return true
169		}
170		_, err := os.Stat(filepath.Join(baseDir, name, consts.SkipScanFile))
171		return err == nil
172	}
