174	// isDirReadable returns true if the directory represented by dirEnt is readable
175	func isDirReadable(baseDir string, dirEnt fs.DirEntry) bool {
176		path := filepath.Join(baseDir, dirEnt.Name())
177		res, err := utils.IsDirReadable(path)
178		if !res {
179			log.Warn("Skipping unreadable directory", "path", path, err)
180		}
181		return res
182	}
