 99		allFSDirs := dirMap{}
100		var changedDirs []string
101		s.cnt = &counters{}
102		genres := newCachedGenreRepository(ctx, s.ds.Genre(ctx))
103		s.mapper = newMediaFileMapper(s.rootFolder, genres)
104		refresher := newRefresher(s.ds, s.cacheWarmer, allFSDirs)
105	
106		foldersFound, walkerError := s.getRootFolderWalker(ctx)
107		for {
108			folderStats, more := <-foldersFound
109			if !more {
110				break
111			}
112			progress <- folderStats.AudioFilesCount
113			allFSDirs[folderStats.Path] = folderStats
114	
115			if s.folderHasChanged(folderStats, allDBDirs, lastModifiedSince) {
116				changedDirs = append(changedDirs, folderStats.Path)
117				log.Debug("Processing changed folder", "dir", folderStats.Path)
118				err := s.processChangedDir(ctx, refresher, fullScan, folderStats.Path)
119				if err != nil {
120					log.Error("Error updating folder in the DB", "dir", folderStats.Path, err)
121				}
122			}
123		}
124	
125		if err := <-walkerError; err != nil {
126			log.Error("Scan was interrupted by error. See errors above", err)
127			return 0, err
128		}
129	
130		deletedDirs := s.getDeletedDirs(ctx, allFSDirs, allDBDirs)
131		if len(deletedDirs)+len(changedDirs) == 0 {
132			log.Debug(ctx, "No changes found in Music Folder", "folder", s.rootFolder, "elapsed", time.Since(start))
133			return 0, nil
134		}
135	
136		for _, dir := range deletedDirs {
137			err := s.processDeletedDir(ctx, refresher, dir)
138			if err != nil {
139				log.Error("Error removing deleted folder from DB", "dir", dir, err)
140			}
141		}
142	
143		s.cnt.playlists = 0
144		if conf.Server.AutoImportPlaylists {
145			// Now that all mediafiles are imported/updated, search for and import/update playlists
146			u, _ := request.UserFrom(ctx)
147			for _, dir := range changedDirs {
148				info := allFSDirs[dir]
149				if info.HasPlaylist {
150					if !u.IsAdmin {
151						log.Warn("Playlists will not be imported, as there are no admin users yet, "+
152							"Please create an admin user first, and then update the playlists for them to be imported", "dir", dir)
153					} else {
154						s.cnt.playlists = s.plsSync.processPlaylists(ctx, dir)
